css:
/* Примусовий чорний колір для всього тексту */
* {
    color: #000 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

body {
    font-family: "Times New Roman", serif;
    font-size: 10.5pt;
}

.inv-title {
    text-align: center;
    font-weight: bold;
    font-size: 13pt;
    margin-bottom: 5px;
}

.meta {
    margin-bottom: 10px;
}

table.inv {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed; /* Гарантує стабільність ширини колонок */
}

table.inv th,
table.inv td {
    border: 1px solid #000 !important;
    /* Центрування по вертикалі */
    vertical-align: middle !important; 
    padding: 2px 4px !important;
    line-height: 1.1 !important;
    word-wrap: break-word;
}

table.inv th {
    text-align: center;
    background-color: #f2f2f2 !important; /* Легка заливка шапки */
    font-weight: bold;
}

/* Налаштування ширини та властивостей колонок */
.cell-idx { 
    width: 35px; 
    text-align: center; 
}

.cell-qty { 
    width: 60px; 
    text-align: center; 
    white-space: nowrap; 
}

.cell-numbers { 
    width: 100px; 
    text-align: center; 
    /* Заборона переносу інвентарного номера */
    white-space: nowrap !important; 
}

.cell-mvo { 
    width: 140px; 
    text-align: left; 
    /* Заборона переносу ПІБ (МВО) */
    white-space: nowrap !important; 
}

.right { 
    text-align: right; 
}

.empty { 
    text-align: center; 
    padding: 15px !important; 
}

/* Налаштування для друку */
tr { 
    page-break-inside: avoid; 
}

.sign {
    margin-top: 35px;
    page-break-inside: avoid;
}

@media print {
    @page { 
        margin: 15mm; 
    }
}

html:
{%- set assets = frappe.get_all(
    "oiAsset",
    filters={"location": doc.name},
    fields=["inventory_no", "asset_name", "responsible_employee", "quantity"],
    order_by="asset_name asc"
) -%}

{# Кеш для ПІБ #}
{%- set emp_cache = {} -%}

{%- macro get_full_name(ref) -%}
  {%- if not ref -%}{{ "" }}
  {%- elif emp_cache.get(ref) -%}{{ emp_cache.get(ref) }}
  {%- else -%}
    {%- set val = frappe.db.get_value("hromsEmployee", ref, "full_name")
        or frappe.db.get_value("oiEmployee", ref, "full_name")
        or frappe.db.get_value("User", ref, "full_name")
        or ref -%}
    {%- set _ = emp_cache.update({ref: val}) -%}
    {{ val }}
  {%- endif -%}
{%- endmacro -%}

{%- macro person_short(ref) -%}
  {%- set full = get_full_name(ref) -%}
  {%- if not full -%}—
  {%- else -%}
    {%- set parts = full.split() -%}
    {%- if parts|length == 1 -%}{{ parts[0] }}
    {%- else -%}
      {{ parts[0] }} {% for p in parts[1:] %}{% if p %}{{ p[:1]|upper }}.{% endif %}{% endfor %}
    {%- endif -%}
  {%- endif -%}
{%- endmacro -%}

{%- macro fmt_qty(v) -%}
  {%- if v is not none -%}
    {{ ("%.2f"|format(v)).rstrip('0').rstrip('.') }}
  {%- else -%}-{% endif -%}
{%- endmacro -%}

{%- set ns = namespace(total_qty=0) -%}

<div class="inv-title">
    ОПИС МАЙНА КАБІНЕТА № {{ doc.room }}
</div>

<div class="meta">
    <div><b>Адреса:</b> {{ doc.full_address }}</div>
    <div>
        <b>Відповідальний:</b>
        {{ doc.get("responsible_name") or "-" }}
        {% if doc.responsible_phone %} ({{ doc.responsible_phone }}){% endif %}
    </div>
</div>

<table class="inv">
    <thead>
        <tr>
            <th class="cell-idx">№</th>
            <th>Найменування</th>
            <th class="cell-qty">К-ть</th>
            <th class="cell-numbers">Інв. номер</th>
            <th class="cell-mvo">МВО</th>
        </tr>
    </thead>

    <tbody>
        {% for a in assets %}
        {%- set ns.total_qty = ns.total_qty + (a.quantity or 0) -%}
        <tr>
            <td class="cell-idx">{{ loop.index }}</td>
            <td class="cell-name">{{ a.asset_name }}</td>
            <td class="cell-qty">{{ fmt_qty(a.quantity) }} шт.</td>
            <td class="cell-numbers">{{ a.inventory_no or "" }}</td>
            <td class="cell-mvo">{{ person_short(a.responsible_employee) }}</td>
        </tr>
        {% else %}
        <tr>
            <td colspan="5" class="empty">Немає активів</td>
        </tr>
        {% endfor %}
    </tbody>

    {% if assets %}
    <tfoot>
        <tr>
            <th colspan="2" class="right">Разом:</th>
            <th class="cell-qty">{{ fmt_qty(ns.total_qty) }} шт.</th>
            <th colspan="2"></th>
        </tr>
    </tfoot>
    {% endif %}
</table>

<div class="sign">
    Підпис відповідального: ___________________
</div>
